and f.com_id = #{comId}
and f.for_status = #{forStatus}
and ( f.for_code like '%' || #{keyword} || '%' or f.for_title like '%' || #{keyword} || '%' )
order by f.updated_at desc, f.for_id desc offset #{pstartno} rows fetch next #{onepagelist} rows only

